'use client';

import React, { useState, useId } from 'react';
import type { AudienceType, CampaignConfig, JobseekerMode } from '@/config/campaign.types';
import { HeroActionPanel } from '@/components/ui/HeroActionPanel';
import { Sparkles, CalendarCheck } from 'lucide-react';
import { TenRing } from '@/components/ui/TenRing';

interface CampaignHeroProps {
  audience: AudienceType;
  onAudienceChange: (audience: AudienceType) => void;
  config: CampaignConfig;
  jobseekerMode?: JobseekerMode;
  onJobseekerModeChange?: (mode: JobseekerMode) => void;
  selectedResumeFile?: File | null;
  onSelectedResumeFileChange?: (file: File | null) => void;
  onUserInteracted?: () => void;
}

export const CampaignHero: React.FC<CampaignHeroProps> = ({
  audience,
  onAudienceChange,
  config,
  jobseekerMode = 'without-resume',
  onJobseekerModeChange,
  selectedResumeFile,
  onSelectedResumeFileChange,
  onUserInteracted,
}) => {
  const isJobseeker = audience === 'jobseeker';
  const isTenRingEnabled = config.heroVisual?.tenRing?.enabled !== false;
  const stepperNodeRawId = useId();
  const stepperNodeGradientId = `stepper-grad-${stepperNodeRawId.replace(/[^a-zA-Z0-9_-]/g, '')}`;

  const [activeStepIndex, setActiveStepIndex] = useState(0);
  const [handoffCompleted, setHandoffCompleted] = useState(false);

  // Stepper labels based on audience and mode
  const stepperLabels = !isJobseeker
    ? config.heroStepper.recruiter
    : jobseekerMode === 'with-resume'
    ? config.heroStepper.jobseekerResume
    : config.heroStepper.jobseekerSearch;

  const handleSearchSubmitted = () => {
    setActiveStepIndex(2);
    setHandoffCompleted(true);
  };

  const currentStepIndex = selectedResumeFile ? Math.max(activeStepIndex, 1) : activeStepIndex;

  // Progress arc: step 1 = 0%, step 2 = 33%, step 3 = 66%, handoff completes = 100%
  const progressRatio = handoffCompleted
    ? 1.0
    : currentStepIndex === 2
    ? 0.66
    : currentStepIndex === 1
    ? 0.33
    : 0;

  const nodeCircumference = 2 * Math.PI * 16; // ~100.53

  return (
    <section className="job10-hero">
      {/* Background Photography without artificial gradient overlay */}
      <div className="job10-hero-bg">
        <img
          src="/images/smart-office-talent-matching-banner.png"
          alt="Smart Office Talent Matching — Connecting qualified professionals and hiring teams in 10 minutes on Job10"
          className="job10-hero-img"
          fetchPriority="high"
          loading="eager"
        />
      </div>

      <div className="container-fluid">
        <div className="job10-hero-content-wrapper">
          <div className="job10-hero-grid">
            {/* Eyebrow Pill */}
            <div className="job10-eyebrow-pill">
              <Sparkles className="job10-eyebrow-sparkle" size={13} aria-hidden="true" />
              <span>{config.eyebrow}</span>
            </div>

            {/* Main Headline */}
            <h1 className="job10-hero-headline">
              Your next opportunity
              <br />
              starts in{' '}
              {isTenRingEnabled && config.headlineHighlight.startsWith('10') ? (
                <span className="job10-ten-highlight-wrap">
                  <span className="job10-ten-wrapper">
                    <TenRing />
                    <span className="job10-hero-gradient-text">10</span>
                  </span>
                  <span className="job10-hero-gradient-text">
                    {config.headlineHighlight.slice(2)}
                  </span>
                </span>
              ) : (
                <span className="job10-hero-gradient-text">
                  {config.headlineHighlight}
                </span>
              )}
            </h1>

            {/* Supporting Copy */}
            <p className="job10-hero-description">{config.heroDescription}</p>

            {/* Conversion Panel */}
            <HeroActionPanel
              audience={audience}
              onAudienceChange={onAudienceChange}
              config={config.searchPanel}
              jobseekerMode={jobseekerMode}
              onJobseekerModeChange={onJobseekerModeChange}
              onSearchSubmitted={handleSearchSubmitted}
              selectedResumeFile={selectedResumeFile}
              onSelectedResumeFileChange={onSelectedResumeFileChange}
              onUserInteracted={onUserInteracted}
            />

            {/* Stepper: Single slim text row with End Node */}
            <div className="job10-hero-stepper-row" aria-label="Process overview">
              <div className="job10-hero-stepper-items">
                {stepperLabels.map((label, idx) => {
                  const stepNumber = `0${idx + 1}`;
                  const isActive = idx === currentStepIndex;
                  return (
                    <React.Fragment key={idx}>
                      <span className={`job10-stepper-step ${isActive ? 'is-active' : ''}`}>
                        <span className="job10-stepper-num">{stepNumber}</span>{' '}
                        <span className="job10-stepper-label">{label}</span>
                      </span>
                      {idx < stepperLabels.length - 1 && (
                        <span className="job10-stepper-divider" aria-hidden="true">—</span>
                      )}
                    </React.Fragment>
                  );
                })}

                {/* Stepper End Node: 36px circle with progress arc & CalendarCheck icon */}
                <span className="job10-stepper-divider" aria-hidden="true">—</span>
                <div
                  className="job10-stepper-end-node"
                  role="img"
                  aria-label="Interview"
                >
                  <svg
                    className="job10-stepper-node-svg"
                    viewBox="0 0 36 36"
                    fill="none"
                    xmlns="http://www.w3.org/2000/svg"
                    aria-hidden="true"
                  >
                    <defs>
                      <linearGradient id={stepperNodeGradientId} x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#2563eb" />
                        <stop offset="100%" stopColor="#7c3aed" />
                      </linearGradient>
                    </defs>
                    {/* Base circle border */}
                    <circle
                      cx="18"
                      cy="18"
                      r="16"
                      stroke="#e2e8f0"
                      strokeWidth="2"
                      fill="#ffffff"
                    />
                    {/* Thin progress arc */}
                    {progressRatio > 0 && (
                      <circle
                        cx="18"
                        cy="18"
                        r="16"
                        stroke={`url(#${stepperNodeGradientId})`}
                        strokeWidth="2"
                        strokeLinecap="round"
                        transform="rotate(-90 18 18)"
                        style={{
                          strokeDasharray: `${nodeCircumference} ${nodeCircumference}`,
                          strokeDashoffset: `${nodeCircumference * (1 - progressRatio)}`,
                          transition: 'stroke-dashoffset 400ms ease-out',
                        }}
                      />
                    )}
                  </svg>
                  <CalendarCheck size={16} className="job10-stepper-node-icon" aria-hidden="true" />
                </div>
              </div>
              <p className="job10-hero-stepper-support">{config.heroStepper.supportingLine}</p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};
