'use client';

import React, { useId } from 'react';

export const TenRing: React.FC = () => {
  const rawId = useId();
  // Safe HTML identifier without colons
  const gradientId = `ten-ring-grad-${rawId.replace(/[^a-zA-Z0-9_-]/g, '')}`;

  return (
    <svg
      className="job10-ten-ring-svg"
      viewBox="0 0 48 48"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <defs>
        <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#2563eb" />
          <stop offset="100%" stopColor="#7c3aed" />
        </linearGradient>
      </defs>

      {/* Clock Tick Marks at 12, 3, 6, 9 o'clock (1.5px, slate-300 #cbd5e1) */}
      <line x1="24" y1="2" x2="24" y2="5.5" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" className="job10-ten-ring-tick" />
      <line x1="42.5" y1="24" x2="46" y2="24" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" className="job10-ten-ring-tick" />
      <line x1="24" y1="42.5" x2="24" y2="46" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" className="job10-ten-ring-tick" />
      <line x1="2" y1="24" x2="5.5" y2="24" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" className="job10-ten-ring-tick" />

      {/* Circle stroke 2.5px with blue->indigo gradient, animated 85% arc from 12 o'clock */}
      <circle
        cx="24"
        cy="24"
        r="18.5"
        stroke={`url(#${gradientId})`}
        strokeWidth="2.5"
        strokeLinecap="round"
        transform="rotate(-90 24 24)"
        className="job10-ten-ring-circle"
      />
    </svg>
  );
};
